



















 description, category, weight, height, hp_base, attack_base, defense_base, special_attack_base, special_defense_base, speed_base) VALUES
(152, 'Chikorita', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/152.png', 2, 2, COMMON, 12, NULL, 134, NULL, 269, 'A sweet aroma gently wafts from the leaf on its head. It is docile and loves to soak up the sun''s rays.', 'Leaf Pokemon', 6.4, 0.9, 45, 49, 65, 49, 65, 45),
(153, 'Bayleef', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/153.png', 2, 2, COMMON, 12, NULL, 134, NULL, 269, 'The scent of spices comes from around its neck. Somehow, sniffing it makes you want to fight.', 'Leaf Pokemon', 15.8, 1.2, 60, 62, 80, 63, 80, 60),
(154, 'Meganium', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/154.png', 2, 2, COMMON, 12, NULL, 134, NULL, 269, 'The aroma that rises from its petals contains a substance that calms aggressive feelings.', 'Herb Pokemon', 100.5, 1.8, 80, 82, 100, 83, 100, 80),
(498, 'Tepig', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/498.png', 5, 5, COMMON, 7, NULL, 17, NULL, 217, 'It can deftly dodge its foe''s attacks while shooting fireballs from its nose. It roasts berries before it eats them.', 'Fire Pig Pokemon', 9.9, 0.5, 65, 63, 45, 45, 45, 45),
(499, 'Pignite', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/499.png', 5, 5, COMMON, 7, 10, 17, NULL, 217, 'When its internal fire flares up, its movements grow sharper and faster. When in trouble, it emits smoke.', 'Fire Pig Pokemon', 55.5, 1.0, 90, 93, 55, 70, 55, 55),
(500, 'Emboar', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/500.png', 5, 5, COMMON, 7, 10, 17, NULL, 294, 'It can throw a fire punch by setting its fists on fire with its fiery chin. It cares deeply about its friends.', 'Mega Fire Pig Pokemon', 150.0, 1.6, 110, 123, 65, 100, 65, 65),
(158, 'Totodile', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/158.png', 2, 2, COMMON, 2, NULL, 220, NULL, 302, 'Its well-developed jaws are powerful and capable of crushing anything. Even its trainer must be careful.', 'Big Jaw Pokemon', 9.5, 0.6, 50, 65, 64, 44, 48, 43),
(159, 'Croconaw', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/159.png', 2, 2, COMMON, 2, NULL, 220, NULL, 302, 'If it loses a fang, a new one grows back in its place. There are always 48 fangs lining its mouth.', 'Big Jaw Pokemon', 25.0, 1.1, 65, 80, 80, 59, 63, 58),
(160, 'Feraligatr', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/160.png', 2, 2, COMMON, 2, NULL, 220, NULL, 302, 'When it bites with its massive and powerful jaws, it shakes its head and savagely tears its victim up.', 'Big Jaw Pokemon', 88.8, 2.3, 85, 105, 100, 79, 83, 78),
(661, 'Fletchling', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/661.png', 6, 6, COMMON, 11, 18, 246, NULL, 67, 'These friendly Pokemon send signals to one another with beautiful chirps and tail-feather movements.', 'Tiny Robin Pokemon', 1.7, 0.3, 45, 50, 43, 40, 38, 62),
(662, 'Fletchinder', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/662.png', 6, 6, COMMON, 7, 18, 254, NULL, 67, 'From its beak, it expels embers that set the tall grass on fire. Then it pounces on the bewildered prey that pop out of the grass.', 'Ember Pokemon', 16.0, 0.7, 62, 73, 55, 56, 52, 84),
(663, 'Talonflame', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/663.png', 6, 6, COMMON, 7, 18, 254, NULL, 67, 'In the fever of an exciting battle, it showers embers from the gaps between its feathers and takes to the air.', 'Scorching Pokemon', 24.5, 1.2, 78, 81, 71, 74, 69, 126),
(659, 'Bunnelby', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/659.png', 6, 6, COMMON, 11, NULL, 287, 23, 259, 'They use their large ears to dig burrows. They will dig the whole night through.', 'Digging Pokemon', 5.0, 0.4, 38, 36, 38, 32, 36, 57),
(660, 'Diggersby', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/660.png', 6, 6, COMMON, 11, 16, 287, 23, 259, 'With their powerful ears, they can heft boulders of a ton or more with ease. They can be a big help at construction sites.', 'Digging Pokemon', 42.4, 1.0, 85, 56, 77, 50, 77, 78),
(664, 'Scatterbug', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/664.png', 6, 6, COMMON, 3, NULL, 303, 250, 256, 'When under attack from bird Pokemon, it spews a poisonous black powder that causes paralysis on contact.', 'Scatterdust Pokemon', 2.5, 0.3, 38, 35, 40, 27, 25, 35),
(665, 'Spewpa', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/665.png', 6, 6, COMMON, 3, NULL, 178, NULL, 256, 'It lives hidden within thicket shadows. When predators attack, it quickly bristles the fur covering its body in an effort to threaten them.', 'Scatterdust Pokemon', 8.4, 0.3, 45, 22, 60, 27, 30, 29),
(666, 'Vivillon', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/666.png', 6, 6, COMMON, 3, 18, 303, 250, 256, 'Vivillon with many different patterns are found all over the world. These patterns are affected by the climate of their habitat.', 'Scale Pokemon', 17.0, 1.2, 80, 52, 50, 90, 50, 89),
(13, 'Weedle', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/13.png', 1, 1, COMMON, 3, 17, 303, NULL, 164, 'Often found in forests, eating leaves. It has a sharp venomous stinger on its head.', 'Hairy Bug Pokemon', 3.2, 0.3, 40, 35, 30, 20, 20, 50),
(14, 'Kakuna', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/14.png', 1, 1, COMMON, 3, 17, 178, NULL, NULL, 'Almost incapable of moving, this Pokemon can only harden its shell to protect itself from predators.', 'Cocoon Pokemon', 10.0, 0.6, 45, 25, 50, 25, 25, 35),
(15, 'Beedrill', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/15.png', 1, 1, COMMON, 3, 17, 315, NULL, 183, 'It has three poisonous stingers on its forelegs and its tail. They are used to jab its enemy repeatedly.', 'Poison Bee Pokemon', 29.5, 1.0, 65, 90, 40, 45, 80, 75),
(16, 'Pidgey', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/16.png', 1, 1, COMMON, 11, 18, 267, 209, 246, 'A common sight in forests and woods. It flaps its wings at ground level to kick up blinding sand.', 'Tiny Bird Pokemon', 1.8, 0.3, 40, 45, 40, 35, 35, 56),
(17, 'Pidgeotto', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/17.png', 1, 1, COMMON, 11, 18, 267, 209, 246, 'Very protective of its sprawling territorial area, this Pokemon will fiercely peck at any intruder.', 'Bird Pokemon', 30.0, 1.1, 63, 60, 55, 50, 50, 71),
(18, 'Pidgeot', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/18.png', 1, 1, COMMON, 11, 18, 267, 209, 246, 'When hunting, it skims the surface of water at high speed to pick off unwary prey such as MAGIKARP.', 'Bird Pokemon', 39.5, 1.5, 83, 80, 75, 70, 70, 101),
(179, 'Mareep', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/179.png', 2, 2, COMMON, 5, NULL, 310, NULL, 288, 'If static electricity builds in its body, its fleece doubles in volume. Touching it will shock you.', 'Wool Pokemon', 7.8, 0.6, 55, 40, 40, 65, 45, 35),
(180, 'Flaaffy', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/180.png', 2, 2, COMMON, 5, NULL, 310, NULL, 288, 'As a result of storing too much electricity, it developed patches where even downy wool won''t grow.', 'Wool Pokemon', 13.3, 0.8, 70, 55, 55, 80, 60, 45),
(181, 'Ampharos', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/181.png', 2, 2, COMMON, 5, NULL, 310, NULL, 288, 'The tail''s tip shines brightly and can be seen from far away. It acts as a beacon for lost people.', 'Light Pokemon', 61.5, 1.4, 90, 75, 85, 115, 90, 55),
(504, 'Patrat', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/504.png', 5, 5, COMMON, 11, NULL, 164, 267, 242, 'Using food stored in cheek pouches, they can keep watch for days. They use their tails to communicate with others.', 'Scout Pokemon', 11.6, 0.5, 45, 55, 39, 35, 39, 42),
(505, 'Watchog', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/505.png', 5, 5, COMMON, 11, NULL, 262, 267, 242, 'When they see an enemy, their tails stand high, and they spit the seeds of berries stored in their cheek pouches.', 'Lookout Pokemon', 27.0, 1.1, 60, 85, 69, 60, 69, 77),
(406, 'Budew', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/406.png', 4, 4, COMMON, 12, 17, 282, 143, 269, 'Over the winter, it closes its bud and endures the cold. In spring, the bud opens and releases pollen.', 'Bud Pokemon', 1.2, 0.2, 40, 30, 35, 50, 70, 55),
(315, 'Roselia', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/315.png', 3, 3, COMMON, 12, 17, 282, 143, 269, 'ROSELIA shoots sharp thorns as projectiles at any opponent that tries to steal the flowers on its arms. The aroma of this Pokemon brings serenity to living things.', 'Thorn Pokemon', 2.0, 0.3, 50, 60, 45, 100, 80, 65),
(407, 'Roserade', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/407.png', 4, 4, COMMON, 12, 17, 282, 143, 318, 'It attracts prey with a sweet aroma, then downs it with thorny whips hidden in its arms.', 'Bouquet Pokemon', 14.5, 0.9, 60, 70, 65, 125, 105, 90),
(129, 'Magikarp', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/129.png', 1, 1, COMMON, 2, NULL, 316, NULL, 159, 'In the distant past, it was somewhat stronger than the horribly weak descendants that exist today.', 'Fish Pokemon', 10.0, 0.9, 20, 10, 55, 15, 20, 80),
(130, 'Gyarados', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/130.png', 1, 1, COMMON, 2, 18, 264, NULL, 281, 'Once it begins to rampage, a GYARADOS will burn everything down, even in a harsh storm.', 'Atrocious Pokemon', 235.0, 6.5, 95, 125, 79, 60, 100, 81),
(688, 'Binacle', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/688.png', 6, 6, COMMON, 14, 2, 221, 183, 286, 'Two Binacle live together on one rock. When they fight, one of them will move to a different rock.', 'Two-Handed Pokemon', 31.0, 0.5, 42, 52, 67, 39, 56, 50),
(689, 'Barbaracle', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/689.png', 6, 6, COMMON, 14, 2, 221, 183, 286, 'When they evolve, two Binacle multiply into seven. They fight with the power of seven Binacle.', 'Collective Pokemon', 96.0, 1.3, 72, 105, 115, 54, 86, 68),
(120, 'Staryu', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/120.png', 1, 1, COMMON, 2, NULL, 262, 282, 242, 'If its body is torn, it can grow back if the red core remains. The core flashes at midnight.', 'Star Shape Pokemon', 34.5, 0.8, 30, 45, 55, 70, 55, 85),
(121, 'Starmie', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/121.png', 1, 1, COMMON, 2, 13, 262, 282, 242, 'Its central core glows with the seven colors of the rainbow. Some people value the core as a gem.', 'Mysterious Pokemon', 80.0, 1.1, 60, 75, 85, 100, 85, 115),
(669, 'Flabébé', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/669.png', 6, 6, COMMON, 8, NULL, 61, NULL, 207, 'It draws out and controls the hidden power of flowers. The flower Flabébé holds is most likely part of its body.', 'Single Bloom Pokemon', 0.1, 0.1, 44, 38, 39, 61, 79, 42),
(670, 'Floette', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/670.png', 6, 6, COMMON, 8, NULL, 61, NULL, 207, 'It flutters around fields of flowers and cares for flowers that are starting to wilt. It draws out the hidden power of flowers to battle.', 'Single Bloom Pokemon', 0.9, 0.2, 54, 45, 47, 75, 98, 52),
(671, 'Florges', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/671.png', 6, 6, COMMON, 8, NULL, 61, NULL, 207, 'It claims exquisite flower gardens as its territory, and it obtains power from basking in the energy emitted by flowering plants.', 'Garden Pokemon', 10.0, 1.1, 78, 65, 68, 112, 154, 75),
(672, 'Skiddo', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/672.png', 6, 6, COMMON, 12, NULL, 170, NULL, 74, 'Thought to be one of the first Pokemon to live in harmony with humans, it has a placid disposition.', 'Mount Pokemon', 31.0, 0.9, 66, 65, 48, 62, 57, 52),
(673, 'Gogoat', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/673.png', 6, 6, COMMON, 12, NULL, 170, NULL, 74, 'It can tell how its Trainer is feeling by subtle shifts in the grip on its horns. This empathic sense lets them run as if one being.', 'Mount Pokemon', 91.0, 1.7, 123, 100, 62, 97, 81, 68),
(677, 'Espurr', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/677.png', 6, 6, COMMON, 13, NULL, 267, 96, 285, 'The organ that emits its intense psychic power is sheltered by its ears to keep power from leaking out.', 'Restraint Pokemon', 3.5, 0.3, 62, 48, 54, 63, 60, 68),
(678, 'Meowstic', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/678.png', 6, 6, COMMON, 13, NULL, 267, 96, 148, 'When in danger, it raises its ears and releases enough psychic power to grind a 10-ton truck into dust.', 'Constraint Pokemon', 8.5, 0.6, 74, 48, 76, 83, 81, 104),
(667, 'Litleo', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/667.png', 6, 6, COMMON, 7, 11, 296, 322, 281, 'The stronger the opponent it faces, the more heat surges from its mane and the more power flows through its body.', 'Lion Cub Pokemon', 13.5, 0.6, 62, 50, 58, 73, 54, 72),
(668, 'Pyroar', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/668.png', 6, 6, COMMON, 7, 11, 296, 322, 281, 'The male with the largest mane of fire is the leader of the pride.', 'Royal Pokemon', 81.5, 1.5, 86, 68, 72, 109, 66, 106),
(674, 'Pancham', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/674.png', 6, 6, COMMON, 10, NULL, 265, 278, 301, 'It does its best to be taken seriously by its enemies, but its glare is not sufficiently intimidating. Chewing on a leaf is its trademark.', 'Playful Pokemon', 8.0, 0.6, 67, 82, 62, 46, 48, 43),
(675, 'Pangoro', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/675.png', 6, 6, COMMON, 10, 15, 265, 278, 301, 'Although it possesses a violent temperament, it won''t put up with bullying. It uses the leaf in its mouth to sense the movements of its enemies.', 'Daunting Pokemon', 136.0, 2.1, 95, 124, 78, 69, 71, 58),
(568, 'Trubbish', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/568.png', 5, 5, COMMON, 17, NULL, 311, 312, 3, 'Inhaling the gas they belch will make you sleep for a week. They prefer unsanitary places.', 'Trash Bag Pokemon', 31.0, 0.6, 50, 50, 62, 40, 62, 65),
(569, 'Garbodor', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/569.png', 5, 5, COMMON, 17, NULL, 311, 326, 3, 'It clenches opponents with its left arm and finishes them off with foul-smelling poison gas belched from its mouth.', 'Trash Heap Pokemon', 107.3, 1.9, 80, 95, 82, 60, 82, 75),
(702, 'Dedenne', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/702.png', 6, 6, COMMON, 5, 8, 23, 287, 288, 'Its whiskers serve as antennas. By sending and receiving electrical waves, it can communicate with others over vast distances.', 'Antenna Pokemon', 2.2, 0.2, 67, 58, 57, 81, 67, 101),
(172, 'Pichu', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/172.png', 2, 2, COMMON, 5, NULL, 310, NULL, 271, 'It is not yet skilled at storing electricity. It may send out a jolt if amused or startled.', 'Tiny Mouse Pokemon', 2.0, 0.3, 20, 40, 15, 35, 35, 60),
(25, 'Pikachu', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/25.png', 1, 7, COMMON, 5, NULL, 310, NULL, 271, 'When several of these Pokemon gather, their electricity could build and cause lightning storms.', 'Mouse Pokemon', 6.0, 0.4, 35, 55, 40, 50, 50, 90),
(26, 'Raichu', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/26.png', 1, 7, COMMON, 5, NULL, 310, NULL, 271, 'Its long tail serves as a ground to protect itself from its own high-voltage power.', 'Mouse Pokemon', 30.0, 0.8, 60, 90, 55, 90, 80, 110),
(173, 'Cleffa', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/173.png', 2, 2, COMMON, 8, NULL, 251, 274, 256, 'Because of its unusual, star-like silhouette, people believe that it came here on a meteor.', 'Star Shape Pokemon', 3.0, 0.3, 50, 25, 28, 45, 55, 15),
(35, 'Clefairy', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/35.png', 1, 1, COMMON, 8, NULL, 251, 274, 256, 'Its magical and cute appeal has many admirers. It is rare and found only in certain areas.', 'Fairy Pokemon', 7.5, 0.6, 70, 45, 48, 60, 65, 35),
(36, 'Clefable', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/36.png', 1, 1, COMMON, 8, NULL, 251, 274, 320, 'A timid fairy Pokemon that is rarely seen. It will run and hide the moment it senses people.', 'Fairy Pokemon', 40.0, 1.3, 95, 70, 73, 95, 90, 60),
(167, 'Spinarak', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/167.png', 2, 2, COMMON, 3, 17, 315, 263, 183, 'It lies still in the same pose for days in its web, waiting for its unsuspecting prey to wander close.', 'String Spit Pokemon', 8.5, 0.5, 40, 60, 40, 40, 40, 30),
(168, 'Ariados', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/168.png', 2, 2, COMMON, 3, 17, 315, 263, 183, 'It spins string not only from its rear but also from its mouth. It is hard to tell which end is which.', 'Long Leg Pokemon', 33.5, 1.1, 70, 90, 70, 60, 70, 40),
(23, 'Ekans', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/23.png', 1, 1, COMMON, 17, NULL, 264, 178, 322, 'Moves silently and stealthily. Eats the eggs of birds, such as PIDGEY and SPEAROW, whole.', 'Snake Pokemon', 6.9, 2.0, 35, 60, 44, 40, 54, 55),
(24, 'Arbok', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/24.png', 1, 1, COMMON, 17, NULL, 264, 178, 322, 'It is rumored that the ferocious warning markings on its belly differ from area to area.', 'Cobra Pokemon', 65.0, 3.5, 60, 95, 69, 65, 79, 80),
(63, 'Abra', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/63.png', 1, 1, COMMON, 13, NULL, 317, 98, 274, 'Using its ability to read minds, it will identify impending danger and TELEPORT to safety.', 'Psi Pokemon', 19.5, 0.9, 25, 20, 15, 105, 55, 90),
(64, 'Kadabra', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/64.png', 1, 1, COMMON, 13, NULL, 317, 98, 274, 'It emits special alpha waves from its body that induce headaches just by being close by.', 'Psi Pokemon', 56.5, 1.3, 40, 35, 30, 120, 70, 105),
(65, 'Alakazam', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/65.png', 1, 1, COMMON, 13, NULL, 317, 98, 274, 'Its brain can outperform a supercomputer. Its intelligence quotient is said to be 5,000.', 'Psi Pokemon', 48.0, 1.5, 55, 50, 45, 135, 95, 120),
(92, 'Gastly', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/92.png', 1, 1, COMMON, 6, 17, 270, NULL, NULL, 'Almost invisible, this gaseous Pokemon cloaks the target and puts it to sleep without notice.', 'Gas Pokemon', 0.1, 1.3, 30, 35, 30, 100, 35, 80),
(93, 'Haunter', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/93.png', 1, 1, COMMON, 6, 17, 270, NULL, NULL, 'Because of its ability to slip through block walls, it is said to be from another dimension.', 'Gas Pokemon', 0.1, 1.6, 45, 50, 45, 115, 55, 95),
(94, 'Gengar', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/94.png', 1, 1, COMMON, 6, 17, 37, NULL, NULL, 'Under a full moon, this Pokemon likes to mimic the shadows of people and laugh at their fright.', 'Shadow Pokemon', 40.5, 1.5, 60, 65, 60, 130, 75, 110),
(543, 'Venipede', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/543.png', 5, 5, COMMON, 3, 17, 143, 315, 186, 'Its bite injects a potent poison, enough to paralyze large bird Pokemon that try to prey on it.', 'Centipede Pokemon', 5.3, 0.4, 30, 45, 59, 30, 39, 57),
(544, 'Whirlipede', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/544.png', 5, 5, COMMON, 3, 17, 143, 315, 186, 'Protected by a hard shell, it spins its body like a wheel and crashes furiously into its enemies.', 'Curlipede Pokemon', 58.5, 1.2, 40, 55, 99, 40, 79, 47),
(545, 'Scolipede', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/545.png', 5, 5, COMMON, 3, 17, 143, 315, 186, 'With quick movements, it chases down its foes, attacking relentlessly with its horns until it prevails.', 'Megapede Pokemon', 200.5, 2.5, 60, 100, 89, 55, 69, 112),
(679, 'Honedge', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/679.png', 6, 6, COMMON, 1, 6, 283, NULL, NULL, 'Apparently this Pokemon is born when a departed spirit inhabits a sword. It attaches itself to people and drinks their life force.', 'Sword Pokemon', 2.0, 0.8, 45, 80, 100, 35, 37, 28),
(680, 'Doublade', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/680.png', 6, 6, COMMON, 1, 6, 283, NULL, NULL, 'When Honedge evolves, it divides into two swords, which cooperate via telepathy to coordinate attacks and slash their enemies to ribbons.', 'Sword Pokemon', 4.5, 0.8, 59, 110, 150, 45, 49, 35),
(681, 'Aegislash', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/681.png', 6, 6, COMMON, 1, 6, 194, NULL, NULL, 'Generations of kings were attended by these Pokemon, which used their spectral power to manipulate and control people and Pokemon.', 'Royal Sword Pokemon', 53.0, 1.7, 60, 50, 140, 50, 140, 60),
