(372, 'Shelgon', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/372.png', 3, 3, COMMON, 4, NULL, 297, NULL, 133, 'Inside SHELGON''s armor-like shell, cells are in the midst of transformation to create an entirely new body. This Pokemon''s shell is extremely heavy, making its movements sluggish.', 'Endurance Pokemon', 110.5, 1.1, 65, 95, 100, 60, 50, 50),
(373, 'Salamence', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/373.png', 3, 3, COMMON, 4, 18, 264, NULL, 281, 'SALAMENCE came about as a result of a strong, long-held dream of growing wings. It is said that this powerful desire triggered a sudden mutation in this Pokemon''s cells, causing it to sprout its magnificent wings.', 'Dragon Pokemon', 102.6, 1.5, 95, 135, 80, 110, 80, 100),
(115, 'Kangaskhan', 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/115.png', 1, 1, COMMON, 11, NULL, 253, 301, 98, 'The infant rarely ventures out of its mother''s protective pouch until it is 3 years old.', 'Parent Pokemon', 80.0, 2.2, 105, 95, 80, 40, 80, 90),
